function calcularValorMilheiro(params) {
  // Tabela de valores por 1000 milhas para cada programa
  const valores = {
    "LATAM PASS": 27.00,
    "LATAM AIRLINES": 27.00,
    "SMILES": 17.00,
    "AZUL": 18.00
  };

  // Determinar o valor por 1000 milhas, com fallback para 17.00 se o programa não estiver na tabela
  const valorPor1000 = valores[params.programaFidelidade] || 17.00;

  // Calcular valores separados para ida e volta
  const valorMilheiroIda = (params.milhasIda / 1000) * valorPor1000;
  const valorMilheiroVolta = (params.milhasVolta / 1000) * valorPor1000;

  // Calcular o valor total do milheiro (ida + volta)
  const valorMilheiroTotal = valorMilheiroIda + valorMilheiroVolta;

  // Se precoOriginal foi fornecido, calcular preços ajustados
  let precoAjustado = 0;
  let precoGoogleAjustado = 0;

  if (params.precoOriginal) {
    // Ajustar o preço com base no valor do milheiro (10% de desconto como exemplo)
    precoAjustado = params.precoOriginal - (valorMilheiroTotal * 0.1);

    // Variação aleatória para o preço do Google (entre -42 e +42)
    const variacao = Math.floor(Math.random() * 84) - 42;
    precoGoogleAjustado = params.precoOriginal + variacao;
  }

  // Formatar os números com 2 casas decimais
  return [
    {
      json: {
        valorPorMil: valorPor1000.toFixed(2),
        valorMilheiroIda: valorMilheiroIda.toFixed(2),
        valorMilheiroVolta: valorMilheiroVolta.toFixed(2),
        valorMilheiroTotal: valorMilheiroTotal.toFixed(2),
        precoAjustado: precoAjustado.toFixed(2),
        precoGoogleAjustado: precoGoogleAjustado.toFixed(2)
      }
    }
  ];
}

